func load_texture(name: String, path: String) -> ImageTexture:
    var image: Image = Image.load_from_file(path)
    return ImageTexture.create_from_image(image)

func get_texture_from_sheet(x: int, y: int, width: int, height: int, sprite_sheet: ImageTexture) -> ImageTexture:
    var image: Image = sprite_sheet.get_image().get_region(Rect2i(x, y, width, height))
    return ImageTexture.create_from_image(image)

func get_animated_sprite_2d(animation_name: String, textures: Array[Texture2D], durations: Array[float]) -> AnimatedSprite2D:
    var sprite_frames: SpriteFrames = SpriteFrames.new()
    var animated_sprite_2d: AnimatedSprite2D = AnimatedSprite2D.new()
    animated_sprite_2d.sprite_frames = sprite_frames
    add_animation_to_sprite_frames(sprite_frames, animation_name, textures, durations)
    return animated_sprite_2d


func add_animation_to_sprite_frames(sprite_frames: SpriteFrames, animation_name: String, textures: Array[Texture2D], durations: Array[float]) -> void:
    sprite_frames.add_animation(animation_name)
    for i in len(textures):
	sprite_frames.add_frame(
	    animation_name,
	    textures[i],
	    durations[i]
	)
